llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Zilascorb(2H), a benzylidene-protected ascorbic acid derivative, had plasma-derived absolute oral bioavailability of 32±12% in patients, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "D-xylose, a small polar sugar, had oral bioavailability of 0.98 versus i.v. in healthy volunteers, showing that small polar carbohydrates can be nearly completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "D-ribose was reported to have high systemic bioavailability with minimal first-pass effect in healthy subjects, supporting good oral absorption for small polar sugars.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fructose had only 14.5% systemic availability after an oral drink in healthy volunteers, but this low value is driven by extensive first-pass splanchnic extraction, a mechanism not applicable to ascorbic acid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest relevant evidence, zilascorb(2H), an ascorbic acid derivative, shows absolute oral bioavailability of 32-34% in patients, above the 20% threshold. Additional small polar sugar data support good oral absorption. The only low value, fructose, is due to specific first-pass metabolism and does not transfer to ascorbic acid. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ascorbic acid itself is present; the closest evidence is a protected derivative/prodrug.",
    "Oral bioavailability of ascorbic acid is dose-dependent, and the evidence set does not cover the dose range relevant to the query.",
    "Morgan similarity scores for the sugar analogues are low, so their transferability is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

